import{_ as i,o as a,c as r,a2 as l}from"./chunks/framework.D3sJ1xc1.js";const h=JSON.parse('{"title":"📜 Regulament EMS (Română)","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-ems.md","filePath":"regulament-ems.md"}'),t={name:"regulament-ems.md"};function o(n,e,u,c,s,d){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="📜-regulament-ems-romana" tabindex="-1">📜 Regulament EMS (Română) <a class="header-anchor" href="#📜-regulament-ems-romana" aria-label="Permalink to &quot;📜 Regulament EMS (Română)&quot;">​</a></h1><hr><h2 id="cap-1-dispozitii-generale" tabindex="-1">CAP. 1 - DISPOZIȚII GENERALE <a class="header-anchor" href="#cap-1-dispozitii-generale" aria-label="Permalink to &quot;CAP. 1 - DISPOZIȚII GENERALE&quot;">​</a></h2><h3 id="_1-1-principii-de-functionare" tabindex="-1">1.1 Principii de funcționare <a class="header-anchor" href="#_1-1-principii-de-functionare" aria-label="Permalink to &quot;1.1 Principii de funcționare&quot;">​</a></h3><p>Departamentul Medical <strong>Legacy Of CLT</strong> funcționează după principii inspirate din serviciile reale de intervenție și urgență.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este obligatorie respectarea lanțului de comandă.</li><li>Toate intervențiile trebuie desfășurate exclusiv în context <strong>Roleplay (IC)</strong>.</li><li>Ordinele superiorilor trebuie respectate în limitele regulamentului.</li><li>Toți membrii trebuie să respecte Regulamentul General al Serverului.</li><li>Toți membrii trebuie să respecte Regulamentul EMS.</li><li>Toți membrii trebuie să respecte Codul de Conduită.</li><li>Toți membrii trebuie să respecte directivele conducerii.</li></ul><hr><h3 id="_1-2-conditii-de-recrutare" tabindex="-1">1.2 Condiții de recrutare <a class="header-anchor" href="#_1-2-conditii-de-recrutare" aria-label="Permalink to &quot;1.2 Condiții de recrutare&quot;">​</a></h3><p>Accesul în cadrul Departamentului Medical este permis doar persoanelor care îndeplinesc condițiile stabilite.</p><h3 id="conditii" tabindex="-1">Condiții <a class="header-anchor" href="#conditii" aria-label="Permalink to &quot;Condiții&quot;">​</a></h3><ul><li>Cazier curat.</li><li>Fără aplicații active într-o altă facțiune guvernamentală.</li><li>Acceptarea tuturor regulamentelor departamentului.</li></ul><hr><h3 id="_1-3-comportamentul-personalului" tabindex="-1">1.3 Comportamentul personalului <a class="header-anchor" href="#_1-3-comportamentul-personalului" aria-label="Permalink to &quot;1.3 Comportamentul personalului&quot;">​</a></h3><p>Fiecare membru trebuie să reprezinte departamentul într-un mod profesionist.</p><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Respectă colegii și cetățenii.</li><li>Utilizează un limbaj civilizat.</li><li>Menține o conduită profesională.</li><li>Este interzisă folosirea funcțiilor EMS în interes personal.</li></ul><hr><h2 id="cap-2-reguli-operationale" tabindex="-1">CAP. 2 - REGULI OPERAȚIONALE <a class="header-anchor" href="#cap-2-reguli-operationale" aria-label="Permalink to &quot;CAP. 2 - REGULI OPERAȚIONALE&quot;">​</a></h2><h3 id="_2-1-interventii-si-apeluri" tabindex="-1">2.1 Intervenții și apeluri <a class="header-anchor" href="#_2-1-interventii-si-apeluri" aria-label="Permalink to &quot;2.1 Intervenții și apeluri&quot;">​</a></h3><p>Salvarea vieților reprezintă prioritatea principală a Departamentului Medical.</p><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Prioritizează acordarea primului ajutor.</li><li>Este interzisă părăsirea unei intervenții înainte de finalizarea procedurilor medicale.</li><li>După preluarea unui apel, ceilalți membri nu pot interveni fără acordul echipajului responsabil.</li><li>Preluarea apelurilor trebuie anunțată prin canalele oficiale.</li><li>Ignorarea persoanelor aflate în stare critică constituie abatere gravă.</li><li>Refuzul acordării primului ajutor este interzis.</li><li>Apelurile trebuie să respecte standardele Roleplay.</li><li>Solicitările făcute doar pentru obținerea unui revive nu sunt considerate apeluri valide.</li></ul><hr><h3 id="_2-2-vehicule-si-echipamente" tabindex="-1">2.2 Vehicule și echipamente <a class="header-anchor" href="#_2-2-vehicule-si-echipamente" aria-label="Permalink to &quot;2.2 Vehicule și echipamente&quot;">​</a></h3><p>Vehiculele și echipamentele departamentului sunt destinate exclusiv activităților medicale.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Vehiculele EMS pot fi utilizate doar în interes de serviciu.</li><li>Utilizarea autospecialelor în scop personal este interzisă.</li><li>Girofarurile și sirenele pot fi folosite doar în timpul intervențiilor oficiale.</li><li>Elicopterul medical poate fi utilizat doar în cazuri justificate.</li><li>Abuzul de vehicule sau echipamente poate atrage sancțiuni disciplinare.</li><li>Autospecialele trebuie parcate doar în zonele destinate departamentului.</li><li>Vehiculele trebuie încuiate atunci când nu sunt utilizate.</li><li>Patrulele medicale pot fi formate din maximum <strong>3 membri</strong>.</li></ul><hr><h3 id="_2-3-utilizarea-elicopterului" tabindex="-1">2.3 Utilizarea elicopterului <a class="header-anchor" href="#_2-3-utilizarea-elicopterului" aria-label="Permalink to &quot;2.3 Utilizarea elicopterului&quot;">​</a></h3><p>Elicopterul medical poate fi folosit doar în situații speciale.</p><h3 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h3><ul><li>Intervenții în zone greu accesibile.</li><li>Accidente grave.</li><li>Situații critice desfășurate în afara orașului.</li></ul><hr><h3 id="_2-4-conduita-si-responsabilitate" tabindex="-1">2.4 Conduită și responsabilitate <a class="header-anchor" href="#_2-4-conduita-si-responsabilitate" aria-label="Permalink to &quot;2.4 Conduită și responsabilitate&quot;">​</a></h3><p>Membrii EMS trebuie să respecte permanent statutul departamentului.</p><h3 id="este-interzis" tabindex="-1">Este interzis <a class="header-anchor" href="#este-interzis" aria-label="Permalink to &quot;Este interzis&quot;">​</a></h3><ul><li>Participarea la jafuri.</li><li>Asistarea activităților ilegale.</li><li>Comiterea de asasinate.</li><li>Deținerea obiectelor ilegale.</li><li>Solicitarea sau acceptarea mitei.</li><li>Staționarea AFK în timpul serviciului.</li></ul><h3 id="reguli-4" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-4" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Orice ilegalitate descoperită prin Roleplay poate conduce la demitere.</li><li>Demisia trebuie realizată prin procedură Roleplay și aprobată de conducere.</li></ul><hr><h2 id="cap-3-activitate-si-prezenta" tabindex="-1">CAP. 3 - ACTIVITATE ȘI PREZENȚĂ <a class="header-anchor" href="#cap-3-activitate-si-prezenta" aria-label="Permalink to &quot;CAP. 3 - ACTIVITATE ȘI PREZENȚĂ&quot;">​</a></h2><h3 id="_3-1-activitatea-membrilor" tabindex="-1">3.1 Activitatea membrilor <a class="header-anchor" href="#_3-1-activitatea-membrilor" aria-label="Permalink to &quot;3.1 Activitatea membrilor&quot;">​</a></h3><p>Participarea activă în cadrul departamentului este obligatorie.</p><h3 id="reguli-5" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-5" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Membrii trebuie să fie activi.</li><li>Participarea la activitățile departamentului este obligatorie.</li><li>Inactivitatea fără aprobare poate conduce la eliminarea din departament.</li></ul><hr><h3 id="_3-2-invoiri-si-concedii" tabindex="-1">3.2 Învoiri și concedii <a class="header-anchor" href="#_3-2-invoiri-si-concedii" aria-label="Permalink to &quot;3.2 Învoiri și concedii&quot;">​</a></h3><p>În situații justificate, membrii pot solicita perioade de inactivitate.</p><h3 id="reguli-6" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-6" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Cererile de concediu trebuie depuse prin canalele oficiale.</li><li>Membrii aflați în concediu sunt scutiți de raportul săptămânal.</li><li>În perioada concediului nu se pot acorda promovări.</li></ul><hr><h2 id="cap-4-promovari" tabindex="-1">CAP. 4 - PROMOVĂRI <a class="header-anchor" href="#cap-4-promovari" aria-label="Permalink to &quot;CAP. 4 - PROMOVĂRI&quot;">​</a></h2><h3 id="_4-1-criterii-de-promovare" tabindex="-1">4.1 Criterii de promovare <a class="header-anchor" href="#_4-1-criterii-de-promovare" aria-label="Permalink to &quot;4.1 Criterii de promovare&quot;">​</a></h3><p>Promovările sunt acordate exclusiv de conducerea departamentului.</p><h3 id="sunt-evaluate" tabindex="-1">Sunt evaluate <a class="header-anchor" href="#sunt-evaluate" aria-label="Permalink to &quot;Sunt evaluate&quot;">​</a></h3><ul><li>Activitatea.</li><li>Implicarea.</li><li>Comportamentul.</li><li>Profesionalismul.</li><li>Performanța în intervenții.</li><li>Respectarea regulamentelor.</li></ul><hr><h3 id="_4-2-conditii" tabindex="-1">4.2 Condiții <a class="header-anchor" href="#_4-2-conditii" aria-label="Permalink to &quot;4.2 Condiții&quot;">​</a></h3><p>Anumite grade necesită îndeplinirea unor condiții suplimentare.</p><h3 id="cerinte" tabindex="-1">Cerințe <a class="header-anchor" href="#cerinte" aria-label="Permalink to &quot;Cerințe&quot;">​</a></h3><ul><li>Perioadă minimă de activitate.</li><li>Rapoarte complete.</li><li>Promovarea examenelor interne.</li><li>Implicare constantă în activitățile departamentului.</li></ul><hr><h3 id="_4-3-solicitarea-promovarilor" tabindex="-1">4.3 Solicitarea promovărilor <a class="header-anchor" href="#_4-3-solicitarea-promovarilor" aria-label="Permalink to &quot;4.3 Solicitarea promovărilor&quot;">​</a></h3><h3 id="reguli-7" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-7" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Solicitarea repetată a promovărilor este descurajată.</li><li>Insistențele pot influența negativ evaluarea unui membru.</li></ul><hr><h2 id="cap-5-comunicare-si-dispecerat" tabindex="-1">CAP. 5 - COMUNICARE ȘI DISPECERAT <a class="header-anchor" href="#cap-5-comunicare-si-dispecerat" aria-label="Permalink to &quot;CAP. 5 - COMUNICARE ȘI DISPECERAT&quot;">​</a></h2><h3 id="_5-1-rolul-dispeceratului" tabindex="-1">5.1 Rolul dispeceratului <a class="header-anchor" href="#_5-1-rolul-dispeceratului" aria-label="Permalink to &quot;5.1 Rolul dispeceratului&quot;">​</a></h3><p>Dispeceratul reprezintă principalul sistem de coordonare al echipajelor medicale.</p><hr><h3 id="_5-2-utilizarea-dispeceratului" tabindex="-1">5.2 Utilizarea dispeceratului <a class="header-anchor" href="#_5-2-utilizarea-dispeceratului" aria-label="Permalink to &quot;5.2 Utilizarea dispeceratului&quot;">​</a></h3><p>Dispeceratul poate fi utilizat doar pentru activități oficiale.</p><h3 id="exemple-1" tabindex="-1">Exemple <a class="header-anchor" href="#exemple-1" aria-label="Permalink to &quot;Exemple&quot;">​</a></h3><ul><li>Preluarea apelurilor.</li><li>Organizarea echipajelor.</li><li>Solicitarea unui superior.</li><li>Coordonarea intervențiilor.</li><li>Transmiterea informațiilor relevante.</li></ul><hr><h3 id="_5-3-comunicarea" tabindex="-1">5.3 Comunicarea <a class="header-anchor" href="#_5-3-comunicarea" aria-label="Permalink to &quot;5.3 Comunicarea&quot;">​</a></h3><h3 id="reguli-8" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-8" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Toate mesajele trebuie formulate în stil Roleplay.</li><li>Sunt interzise conversațiile inutile.</li><li>Sunt interzise discuțiile OOC.</li><li>Sunt interzise mesajele fără relevanță.</li></ul><hr><h3 id="_5-4-monitorizarea-canalelor" tabindex="-1">5.4 Monitorizarea canalelor <a class="header-anchor" href="#_5-4-monitorizarea-canalelor" aria-label="Permalink to &quot;5.4 Monitorizarea canalelor&quot;">​</a></h3><p>Pe durata serviciului, membrii trebuie să urmărească permanent canalele oficiale de comunicare.</p><hr><h2 id="cap-6-dispozitii-finale" tabindex="-1">CAP. 6 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-6-dispozitii-finale" aria-label="Permalink to &quot;CAP. 6 - DISPOZIȚII FINALE&quot;">​</a></h2><h3 id="_6-1-aplicarea-regulamentului" tabindex="-1">6.1 Aplicarea regulamentului <a class="header-anchor" href="#_6-1-aplicarea-regulamentului" aria-label="Permalink to &quot;6.1 Aplicarea regulamentului&quot;">​</a></h3><p>Respectarea prezentului regulament este obligatorie pentru toți membrii Departamentului Medical.</p><h3 id="reguli-9" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-9" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Nerespectarea regulamentului poate atrage sancțiuni disciplinare.</li><li>Conducerea își rezervă dreptul de a interpreta regulamentul în funcție de fiecare situație.</li><li>Regulamentul poate fi modificat ori de câte ori este necesar.</li></ul><hr><h1 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h1><p>Scopul prezentului regulament este menținerea unui departament medical organizat, profesionist și orientat către un <strong>Roleplay</strong> realist și de calitate.</p><p>Respectarea tuturor prevederilor este obligatorie pentru fiecare membru al <strong>EMS Legacy Of CLT</strong>.</p>',92)])])}const m=i(t,[["render",o]]);export{h as __pageData,m as default};
